// The spreadsheet editor shell: toolbar, formula bar and status bar around the
// grid. Every test works through the page as a user would (press, type) and
// reads the result from the workbook model. Every workbook is generated by code.
import type { Locator, Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const NS_MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
const MAX_COLS = 16384;
const MAX_ROWS = 1048576;

const num = (ref: string, value: number, style = 0) => `<c r="${ref}" s="${style}"><v>${value}</v></c>`;
const str = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t>${text}</t></is></c>`;

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

/**
 * "Data": A1=1, B1=2, C1=A1+B1, D1=4 in a format that has everything the
 * toolbar shows (bold, italic, underlined, struck through, 13 pt, red on
 * yellow, right-aligned, wrapped, number format "0.000"); A2=10.5, B2=20.25,
 * A3="text". "Other": A1=5.
 */
const editorWorkbook = once(() =>
  buildXlsx({
    styles:
      `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="${NS_MAIN}">` +
      '<numFmts count="1"><numFmt numFmtId="164" formatCode="0.000"/></numFmts>' +
      '<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font>' +
      '<font><b/><i/><strike/><u/><sz val="13"/><color rgb="FFFF0000"/><name val="Calibri"/></font></fonts>' +
      '<fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill>' +
      '<fill><patternFill patternType="solid"><fgColor rgb="FFFFFF00"/></patternFill></fill></fills>' +
      '<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>' +
      '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>' +
      '<cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>' +
      '<xf numFmtId="164" fontId="1" fillId="2" borderId="0" xfId="0"><alignment horizontal="right" wrapText="1"/></xf></cellXfs>' +
      '</styleSheet>',
    sheets: [
      {
        name: 'Data',
        xml: worksheetXml(
          '<sheetData>' +
            `<row r="1">${num('A1', 1)}${num('B1', 2)}<c r="C1"><f>A1+B1</f><v>3</v></c>${num('D1', 4, 1)}</row>` +
            `<row r="2">${num('A2', 10.5)}${num('B2', 20.25)}</row>` +
            `<row r="3">${str('A3', 'text')}</row>` +
            '</sheetData>',
        ),
      },
      { name: 'Other', xml: worksheetXml(`<sheetData><row r="1">${num('A1', 5)}</row></sheetData>`) },
    ],
  }),
);

/** A1=1, B1=2 and a cell at KO1000: the used area is 1000 x 301 cells, more than the status bar adds up. */
const wideWorkbook = once(() =>
  buildXlsx({
    sheets: [{ name: 'Wide', xml: worksheetXml(`<sheetData><row r="1">${num('A1', 1)}${num('B1', 2)}</row><row r="1000">${num('KO1000', 7)}</row></sheetData>`) }],
  }),
);

interface EditorOptions {
  locale?: string;
  readOnly?: boolean;
  toolbar?: boolean;
  formulaBar?: boolean;
  statusBar?: boolean;
}

async function mount(page: Page, bytes: Uint8Array, options: EditorOptions = {}, into = 'host'): Promise<void> {
  if (!page.url().endsWith('/e2e/pages/editor.html')) {
    await page.goto('/e2e/pages/editor.html');
    await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  }
  await page.evaluate(
    async ({ base64, options, into }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, into);
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options }, into },
  );
  await expect(page.locator(`#${into} .bym-canvas`)).toBeVisible();
}

const select = (page: Page, ref: string, editor = '__editor') =>
  page.evaluate(
    ([ref, editor]) => {
      const api = (window as any).BymOffice;
      (window as any)[editor].view.select(api.parseRange(ref));
    },
    [ref, editor],
  );

const selection = (page: Page): Promise<string> =>
  page.evaluate(() => (window as any).BymOffice.rangeName((window as any).__editor.view.selection.range));

interface CellInfo {
  value: number | string | boolean | null;
  formula: string | null;
  bold: boolean;
  italic: boolean;
  underline: string;
  strike: boolean;
  size: number | null;
  color: string | null;
  fill: string | null;
  horizontal: string | null;
  wrap: boolean;
  numFmt: string;
  borders: string;
}

/** A cell of the shown sheet as the model has it, with its format resolved. */
const cell = (page: Page, ref: string, editor = '__editor'): Promise<CellInfo> =>
  page.evaluate(
    ([ref, editor]) => {
      const api = (window as any).BymOffice;
      const view = (window as any)[editor].view;
      const workbook = view.workbook;
      const at = api.parseCellRef(ref);
      const found = api.getCell(workbook.sheets[view.activeSheet], at.row, at.col);
      const style = api.resolveCellStyle(workbook.styles, found ? found.style : 0);
      const solid = style.fill.type === 'pattern' && style.fill.pattern === 'solid';
      return {
        value: found && found.value !== undefined ? found.value : null,
        formula: found && found.formula ? found.formula.text : null,
        bold: style.font.bold,
        italic: style.font.italic,
        underline: style.font.underline,
        strike: style.font.strike,
        size: style.font.size ?? null,
        color: api.resolveColor(style.font.color, workbook.styles) ?? null,
        fill: solid ? (api.resolveColor(style.fill.fg, workbook.styles) ?? null) : null,
        horizontal: style.alignment.horizontal ?? null,
        wrap: style.alignment.wrapText === true,
        numFmt: style.numFmt,
        borders: ['top', 'right', 'bottom', 'left'].filter((side) => style.border[side] && style.border[side].style).join(' '),
      };
    },
    [ref, editor],
  );

const merges = (page: Page): Promise<string[]> =>
  page.evaluate(() => {
    const view = (window as any).__editor.view;
    return view.workbook.sheets[view.activeSheet].merges.map((merge: any) => (window as any).BymOffice.rangeName(merge));
  });

/** Class of the element with the focus; "bym-input" is the grid. */
const focusedClass = (page: Page): Promise<string> => page.evaluate(() => (document.activeElement ? document.activeElement.className : ''));

const command = (page: Page, name: string, host = '#host') => page.locator(`${host} [data-command="${name}"]`);
const popover = (page: Page, host = '#host') => page.locator(`${host} .bym-popover`);

/** A press with whatever the project has: a finger where there is a touch screen, the mouse elsewhere. */
function presser(hasTouch: boolean | undefined): (target: Locator) => Promise<void> {
  return (target) => (hasTouch ? target.tap() : target.click());
}

/** Waits for the shell's pending update (one animation frame) to have run. */
const settled = (page: Page) => page.evaluate(() => new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve()))));

test.describe('layout', () => {
  test('toolbar, formula bar, grid and status bar share the container; the grid takes what is left', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const boxes = async () => {
      const box = async (selector: string) => (await page.locator(selector).boundingBox())!;
      return { host: await box('#host'), toolbar: await box('#host .bym-toolbar'), formula: await box('#host .bym-formula'), grid: await box('#host .bym-editor-grid'), status: await box('#host .bym-status') };
    };
    let b = await boxes();
    expect(b.toolbar.y).toBeCloseTo(b.host.y, 0);
    expect(b.formula.y).toBeCloseTo(b.toolbar.y + b.toolbar.height, 0);
    expect(b.grid.y).toBeCloseTo(b.formula.y + b.formula.height, 0);
    expect(b.status.y).toBeCloseTo(b.grid.y + b.grid.height, 0);
    expect(b.status.y + b.status.height).toBeCloseTo(b.host.y + b.host.height, 0);
    for (const part of [b.toolbar, b.formula, b.grid, b.status]) expect(part.width).toBeCloseTo(b.host.width, 0);
    expect(b.grid.height).toBeGreaterThan(400);
    await expect(page.locator('#host .bym-tabs')).toBeVisible();
    await expect(page.locator('#host .bym-toolbar')).toHaveAttribute('role', 'toolbar');
    await expect(page.locator('#host .bym-toolbar')).toHaveAttribute('aria-label', 'Formatting');

    // A container that changes size: the bars keep their height, the grid follows.
    const before = b;
    await page.evaluate(() => {
      const host = document.getElementById('host')!;
      host.style.height = '380px';
      host.style.width = '300px';
    });
    await expect.poll(async () => (await boxes()).grid.height).toBeCloseTo(before.grid.height - 180, 0);
    b = await boxes();
    expect(b.toolbar.height).toBe(before.toolbar.height);
    expect(b.status.y + b.status.height).toBeCloseTo(b.host.y + 380, 0);
    expect(b.grid.width).toBeCloseTo(300, 0);
    await expect.poll(() => page.evaluate(() => (window as any).__editor.view.getViewState().width)).toBe(300);
  });

  test('a toolbar wider than the editor scrolls sideways; its controls keep their size and the page does not scroll', async ({ page }) => {
    await mount(page, await editorWorkbook());
    await page.evaluate(() => (document.getElementById('host')!.style.width = '320px'));
    const facts = await page.evaluate(() => {
      const toolbar = document.querySelector('#host .bym-toolbar') as HTMLElement;
      const coarse = matchMedia('(pointer: coarse)').matches;
      const sizes = Array.from(toolbar.querySelectorAll('button')).map((button) => `${button.offsetWidth}x${button.offsetHeight}`);
      toolbar.scrollLeft = 10000;
      return {
        coarse,
        sizes: Array.from(new Set(sizes)),
        buttons: sizes.length,
        scrolls: toolbar.scrollWidth > toolbar.clientWidth,
        scrolled: toolbar.scrollLeft > 0,
        pageWidth: document.documentElement.scrollWidth,
        viewport: document.documentElement.clientWidth,
      };
    });
    expect(facts.buttons).toBe(29);
    expect(facts.sizes).toEqual([facts.coarse ? '40x40' : '32x32']);
    expect(facts.scrolls).toBe(true);
    expect(facts.scrolled).toBe(true);
    expect(facts.pageWidth).toBeLessThanOrEqual(facts.viewport);
    await expect(page.locator('#host .bym-canvas')).toBeVisible();
    await expect(command(page, 'find')).toBeInViewport();
  });

  test('on a phone the editor is as wide as the screen and the grid stays in view', async ({ page, isMobile }) => {
    test.skip(!isMobile, 'the desktop projects have room for the whole toolbar; the narrow case is forced in the test above');
    await mount(page, await editorWorkbook());
    const facts = await page.evaluate(() => {
      const toolbar = document.querySelector('#host .bym-toolbar') as HTMLElement;
      const canvas = document.querySelector('#host .bym-canvas') as HTMLElement;
      return { screen: document.documentElement.clientWidth, toolbar: toolbar.clientWidth, content: toolbar.scrollWidth, canvas: canvas.getBoundingClientRect().width, pageWidth: document.documentElement.scrollWidth };
    });
    expect(facts.toolbar).toBe(facts.screen);
    expect(facts.content).toBeGreaterThan(facts.screen);
    expect(facts.canvas).toBeCloseTo(facts.screen, 0);
    expect(facts.pageWidth).toBe(facts.screen);
  });

  test('each bar can be left out', async ({ page }) => {
    await mount(page, await editorWorkbook(), { toolbar: false, formulaBar: false, statusBar: false });
    await expect(page.locator('#host .bym-toolbar, #host .bym-formula, #host .bym-status')).toHaveCount(0);
    const grid = (await page.locator('#host .bym-editor-grid').boundingBox())!;
    const host = (await page.locator('#host').boundingBox())!;
    expect(grid.height).toBeCloseTo(host.height, 0);
    await select(page, 'B2');
    expect(await selection(page)).toBe('B2');

    await mount(page, await editorWorkbook(), { formulaBar: false });
    await expect(page.locator('#host .bym-toolbar, #host .bym-status')).toHaveCount(2);
    await expect(page.locator('#host .bym-formula')).toHaveCount(0);
  });
});

test.describe('toolbar', () => {
  test('bold, italic, underline and strikethrough switch the selection and show its state', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    await select(page, 'A1:B2');
    const cases: [string, keyof CellInfo, unknown, unknown][] = [
      ['bold', 'bold', true, false],
      ['italic', 'italic', true, false],
      ['underline', 'underline', 'single', 'none'],
      ['strikethrough', 'strike', true, false],
    ];
    for (const [name, field, on, off] of cases) {
      const button = command(page, name);
      await expect(button).toHaveAttribute('aria-pressed', 'false');
      await press(button);
      for (const ref of ['A1', 'B2']) expect((await cell(page, ref))[field], `${name} on ${ref}`).toBe(on);
      await expect(button).toHaveAttribute('aria-pressed', 'true');
      await press(button);
      expect((await cell(page, 'A1'))[field], `${name} off`).toBe(off);
      await expect(button).toHaveAttribute('aria-pressed', 'false');
    }
    // Nothing outside the selection changed.
    expect((await cell(page, 'A3')).bold).toBe(false);
  });

  test('the font size list sets the size and offers a size it does not have while the cell has it', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const size = page.locator('#host .bym-tb-size');
    await expect(size).toHaveValue('11');
    await expect(size.locator('option')).toHaveText(['8', '9', '10', '11', '12', '14', '16', '18', '20', '24', '28', '36']);
    await size.selectOption('14');
    expect((await cell(page, 'A1')).size).toBe(14);
    await expect(size).toHaveValue('14');
    expect(await focusedClass(page)).toBe('bym-input');

    await select(page, 'D1');
    await expect(size).toHaveValue('13');
    await expect(size.locator('option')).toHaveText(['8', '9', '10', '11', '12', '13', '14', '16', '18', '20', '24', '28', '36']);
    await select(page, 'B1');
    await expect(size).toHaveValue('11');
    await expect(size.locator('option')).toHaveCount(12);
  });

  test('the text colour palette opens, applies a colour, shows it and goes back to automatic', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    await select(page, 'A1:B1');
    const button = command(page, 'textColor');
    const bar = button.locator('.bym-icon-bar');
    await expect(button).toHaveAttribute('aria-haspopup', 'dialog');
    await expect(button).toHaveAttribute('aria-expanded', 'false');
    await expect(bar).toHaveAttribute('data-color', '#000000');

    await press(button);
    await expect(popover(page)).toBeVisible();
    await expect(popover(page)).toHaveAttribute('aria-label', 'Text colour');
    await expect(button).toHaveAttribute('aria-expanded', 'true');
    await expect(popover(page).locator('.bym-pop-swatch')).toHaveCount(60);
    await expect(popover(page).locator('.bym-pop-item')).toHaveText(['Automatic']);
    await press(popover(page).locator('[data-color="#FF0000"]'));
    await expect(popover(page)).toHaveCount(0);
    await expect(button).toHaveAttribute('aria-expanded', 'false');
    expect((await cell(page, 'A1')).color).toBe('#FF0000');
    expect((await cell(page, 'B1')).color).toBe('#FF0000');
    await expect(bar).toHaveAttribute('data-color', '#FF0000');
    expect(await focusedClass(page)).toBe('bym-input');

    // The palette marks the colour the cell has; "Automatic" removes it.
    await press(button);
    await expect(popover(page).locator('[aria-pressed="true"]')).toHaveAttribute('data-color', '#FF0000');
    await press(popover(page).locator('.bym-pop-item'));
    expect((await cell(page, 'A1')).color).toBeNull();
    await expect(bar).toHaveAttribute('data-color', '#000000');
  });

  test('the fill palette applies and removes a fill; a second press or a press elsewhere closes it', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    const button = command(page, 'fillColor');
    const bar = button.locator('.bym-icon-bar');
    await expect(bar).toHaveAttribute('data-color', 'none');

    await press(button);
    await expect(popover(page)).toBeVisible();
    await press(button);
    await expect(popover(page)).toHaveCount(0);
    await expect(button).toHaveAttribute('aria-expanded', 'false');

    await press(button);
    await expect(popover(page)).toBeVisible();
    await press(page.locator('#host .bym-status'));
    await expect(popover(page)).toHaveCount(0);
    expect((await cell(page, 'A1')).fill).toBeNull();

    await press(button);
    await expect(popover(page).locator('.bym-pop-item')).toHaveText(['No fill']);
    await press(popover(page).locator('[data-color="#FFF2CC"]'));
    expect((await cell(page, 'A1')).fill).toBe('#FFF2CC');
    await expect(bar).toHaveAttribute('data-color', '#FFF2CC');

    await press(button);
    await press(popover(page).locator('.bym-pop-item'));
    expect((await cell(page, 'A1')).fill).toBeNull();
    await expect(bar).toHaveAttribute('data-color', 'none');
  });

  test('the palette stays inside the editor', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    await page.evaluate(() => (document.getElementById('host')!.style.width = '330px'));
    await press(command(page, 'fillColor'));
    await expect(popover(page)).toBeVisible();
    const box = (await popover(page).boundingBox())!;
    const host = (await page.locator('#host').boundingBox())!;
    expect(box.x).toBeGreaterThanOrEqual(host.x);
    expect(box.x + box.width).toBeLessThanOrEqual(host.x + host.width);
  });

  test('the border menu draws borders by position in the selection', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    await select(page, 'A1:B2');
    const button = command(page, 'borders');
    await expect(button).toHaveAttribute('aria-haspopup', 'menu');
    const choose = async (label: string) => {
      await press(button);
      await expect(popover(page)).toHaveAttribute('role', 'menu');
      await press(popover(page).getByRole('menuitem', { name: label, exact: true }));
      await expect(popover(page)).toHaveCount(0);
    };

    await press(button);
    await expect(popover(page).locator('.bym-pop-item')).toHaveText(['All borders', 'Outside borders', 'Bottom border', 'Top border', 'Left border', 'Right border', 'No borders']);
    await expect(popover(page).locator('.bym-pop-item svg')).toHaveCount(7);
    await press(button);

    await choose('Outside borders');
    expect((await cell(page, 'A1')).borders).toBe('top left');
    expect((await cell(page, 'B2')).borders).toBe('right bottom');
    await choose('All borders');
    expect((await cell(page, 'A1')).borders).toBe('top right bottom left');
    await choose('No borders');
    expect((await cell(page, 'A1')).borders).toBe('');
    await choose('Bottom border');
    expect((await cell(page, 'A1')).borders).toBe('');
    expect((await cell(page, 'A2')).borders).toBe('bottom');
    await choose('No borders');
    for (const [label, side, ref] of [['Top border', 'top', 'B1'], ['Left border', 'left', 'A2'], ['Right border', 'right', 'B1']]) {
      await choose(label);
      expect((await cell(page, ref)).borders, label).toBe(side);
      await choose('No borders');
    }
    expect(await focusedClass(page)).toBe('bym-input');
  });

  test('the alignment buttons work like radio buttons, and the pressed one switches alignment off', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    const pressed = () => Promise.all(['alignLeft', 'alignCenter', 'alignRight'].map((name) => command(page, name).getAttribute('aria-pressed')));
    expect(await pressed()).toEqual(['false', 'false', 'false']);
    for (const [name, value, state] of [
      ['alignLeft', 'left', ['true', 'false', 'false']],
      ['alignCenter', 'center', ['false', 'true', 'false']],
      ['alignRight', 'right', ['false', 'false', 'true']],
    ] as [string, string, string[]][]) {
      await press(command(page, name));
      expect((await cell(page, 'A1')).horizontal).toBe(value);
      await expect.poll(pressed).toEqual(state);
    }
    await press(command(page, 'alignRight'));
    expect((await cell(page, 'A1')).horizontal).toBeNull();
    await expect.poll(pressed).toEqual(['false', 'false', 'false']);
  });

  test('wrap text switches on and off', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    const button = command(page, 'wrapText');
    await press(button);
    expect((await cell(page, 'A1')).wrap).toBe(true);
    await expect(button).toHaveAttribute('aria-pressed', 'true');
    await press(button);
    expect((await cell(page, 'A1')).wrap).toBe(false);
    await expect(button).toHaveAttribute('aria-pressed', 'false');
  });

  test('merge joins the selection and splits it again', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    await select(page, 'A5:B6');
    const button = command(page, 'merge');
    await expect(button).toHaveAttribute('aria-pressed', 'false');
    await press(button);
    expect(await merges(page)).toEqual(['A5:B6']);
    await expect(button).toHaveAttribute('aria-pressed', 'true');
    // One merged cell is one cell: the name box names it, the status bar has nothing to add up.
    await expect(page.locator('#host .bym-namebox')).toHaveValue('A5');
    await press(button);
    expect(await merges(page)).toEqual([]);
    await expect(button).toHaveAttribute('aria-pressed', 'false');
  });

  test('the number format list applies each format and names the one the cell has', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const list = page.locator('#host .bym-tb-format');
    await expect(list).toHaveValue('general');
    await expect(list.locator('option')).toHaveText(['General', 'Number', 'Currency', 'Percent', 'Date', 'Time', 'Text']);
    for (const [kind, code] of [
      ['number', '#,##0.00'],
      ['currency', '"$"#,##0.00'],
      ['percent', '0%'],
      ['date', 'm/d/yyyy'],
      ['time', 'hh:mm'],
      ['text', '@'],
      ['general', 'General'],
    ]) {
      await list.selectOption(kind);
      expect((await cell(page, 'A1')).numFmt, kind).toBe(code);
      await expect(list).toHaveValue(kind);
      expect(await focusedClass(page)).toBe('bym-input');
    }

    // A format that is none of them shows as "Custom", an entry that only exists meanwhile.
    await select(page, 'D1');
    await expect(list).toHaveValue('custom');
    await expect(list.locator('option')).toHaveText(['General', 'Number', 'Currency', 'Percent', 'Date', 'Time', 'Text', 'Custom']);
    await select(page, 'B1');
    await expect(list).toHaveValue('general');
    await expect(list.locator('option')).toHaveCount(7);
  });

  test('currency and date follow the language, and the other language still reads as currency and date', async ({ page }) => {
    await mount(page, await editorWorkbook(), { locale: 'tr' });
    const list = page.locator('#host .bym-tb-format');
    await expect(list.locator('option')).toHaveText(['Genel', 'Sayı', 'Para', 'Yüzde', 'Tarih', 'Saat', 'Metin']);
    await list.selectOption('currency');
    expect((await cell(page, 'A1')).numFmt).toBe('#,##0.00 "₺"');
    await select(page, 'B1');
    await list.selectOption('date');
    expect((await cell(page, 'B1')).numFmt).toBe('dd.mm.yyyy');

    await page.evaluate(() => (window as any).__editor.setLocale('en'));
    await expect(list).toHaveValue('date');
    await select(page, 'A1');
    await expect(list).toHaveValue('currency');
    await expect(list.locator('option')).toHaveCount(7);
  });

  test('the rows and columns menu inserts and deletes around the selection', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    const button = command(page, 'rowsColumns');
    const choose = async (label: string) => {
      await press(button);
      await press(popover(page).getByRole('menuitem', { name: label, exact: true }));
      await expect(popover(page)).toHaveCount(0);
    };
    await select(page, 'A2');
    await press(button);
    await expect(popover(page).locator('.bym-pop-item')).toHaveText([
      'Insert row above',
      'Insert row below',
      'Insert column left',
      'Insert column right',
      'Delete row',
      'Delete column',
      'Freeze panes',
      'Freeze top row',
      'Freeze first column',
    ]);
    await press(button);

    await choose('Insert row above');
    expect((await cell(page, 'A2')).value).toBeNull();
    expect((await cell(page, 'A3')).value).toBe(10.5);
    expect(await focusedClass(page)).toBe('bym-input');

    await select(page, 'A3');
    await choose('Insert row below');
    expect((await cell(page, 'A3')).value).toBe(10.5);
    expect((await cell(page, 'A4')).value).toBeNull();
    expect((await cell(page, 'A5')).value).toBe('text');

    await select(page, 'B1');
    await choose('Insert column left');
    expect((await cell(page, 'B1')).value).toBeNull();
    expect((await cell(page, 'C1')).value).toBe(2);
    await select(page, 'C1');
    await choose('Insert column right');
    expect((await cell(page, 'D1')).value).toBeNull();
    expect((await cell(page, 'E1')).formula).toBe('A1+C1');

    await select(page, 'B1');
    await choose('Delete column');
    expect((await cell(page, 'B1')).value).toBe(2);
    await select(page, 'A2');
    await choose('Delete row');
    expect((await cell(page, 'A2')).value).toBe(10.5);

    // The labels count what is selected; whole rows leave nothing to say about columns.
    await select(page, 'A1:B2');
    await press(button);
    // The active cell is A1: there is nothing above it or left of it to freeze.
    await expect(popover(page).locator('.bym-pop-item')).toHaveText([
      'Insert 2 rows above',
      'Insert 2 rows below',
      'Insert 2 columns left',
      'Insert 2 columns right',
      'Delete 2 rows',
      'Delete 2 columns',
      'Freeze top row',
      'Freeze first column',
    ]);
    await press(button);
    await page.evaluate((right) => (window as any).__editor.view.select({ top: 1, left: 0, bottom: 1, right }), MAX_COLS - 1);
    await press(button);
    await expect(popover(page).locator('.bym-pop-item')).toHaveText(['Insert row above', 'Insert row below', 'Delete row', 'Freeze panes', 'Freeze top row', 'Freeze first column']);
  });

  test('undo and redo are only enabled when there is a step, and take it', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    const undo = command(page, 'undo');
    const redo = command(page, 'redo');
    await expect(undo).toBeDisabled();
    await expect(redo).toBeDisabled();

    await press(command(page, 'bold'));
    await expect(undo).toBeEnabled();
    await expect(redo).toBeDisabled();
    await press(undo);
    expect((await cell(page, 'A1')).bold).toBe(false);
    await expect(undo).toBeDisabled();
    await expect(redo).toBeEnabled();
    await expect(command(page, 'bold')).toHaveAttribute('aria-pressed', 'false');
    await press(redo);
    expect((await cell(page, 'A1')).bold).toBe(true);
    await expect(redo).toBeDisabled();
    await expect(command(page, 'bold')).toHaveAttribute('aria-pressed', 'true');

    // A step made in the grid enables undo as well.
    await page.evaluate(() => (window as any).__editor.view.setCellInput(4, 0, '9'));
    await press(undo);
    expect((await cell(page, 'A5')).value).toBeNull();
    await press(undo);
    await expect(undo).toBeDisabled();
  });

  test('moving the selection shows the format of the new active cell', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const states = () =>
      page.evaluate(() => {
        const host = document.getElementById('host')!;
        const pressed: string[] = [];
        host.querySelectorAll('.bym-toolbar [aria-pressed="true"]').forEach((button) => pressed.push(button.getAttribute('data-command')!));
        return {
          pressed,
          size: (host.querySelector('.bym-tb-size') as HTMLSelectElement).value,
          format: (host.querySelector('.bym-tb-format') as HTMLSelectElement).value,
          text: host.querySelector('[data-command="textColor"] .bym-icon-bar')!.getAttribute('data-color'),
          fill: host.querySelector('[data-command="fillColor"] .bym-icon-bar')!.getAttribute('data-color'),
        };
      });
    // A cell without a vertical alignment is aligned at the bottom: that button is pressed.
    expect(await states()).toEqual({ pressed: ['alignBottom'], size: '11', format: 'general', text: '#000000', fill: 'none' });
    await select(page, 'D1');
    await expect.poll(states).toEqual({ pressed: ['bold', 'italic', 'underline', 'strikethrough', 'alignRight', 'alignBottom', 'wrapText'], size: '13', format: 'custom', text: '#FF0000', fill: '#FFFF00' });
    // With the keyboard, in the grid.
    await page.evaluate(() => (window as any).__editor.view.focus());
    await page.keyboard.press('ArrowLeft');
    await expect.poll(states).toEqual({ pressed: ['alignBottom'], size: '11', format: 'general', text: '#000000', fill: 'none' });
    // The active cell decides, not the rest of the range.
    await select(page, 'C1:D1');
    await expect.poll(states).toMatchObject({ pressed: ['alignBottom'] });
  });

  test('a command that fails says why in the status bar and leaves the workbook alone', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    await page.evaluate((right) => (window as any).__editor.view.select({ top: 0, left: 0, bottom: 1, right }), MAX_COLS - 1);
    await press(command(page, 'merge'));
    const message = page.locator('#host .bym-status-message');
    await expect(message).toHaveText('Whole rows or columns cannot be merged');
    expect(await merges(page)).toEqual([]);
    expect(await focusedClass(page)).toBe('bym-input');
    await select(page, 'A1');
    await expect(message).toHaveText('');
  });
});

test.describe('keyboard and focus', () => {
  test('the buttons are one Tab stop; arrows, Home and End move between them and pass over the lists', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const stops = () =>
      page.evaluate(() => {
        const out: string[] = [];
        document.querySelectorAll('#host .bym-toolbar, #host .bym-toolbar button, #host .bym-toolbar select').forEach((control) => {
          if ((control as HTMLElement).tabIndex === 0) out.push(control.getAttribute('data-command') || control.className);
        });
        return out;
      });
    const focused = () => page.evaluate(() => (document.activeElement ? document.activeElement.getAttribute('data-command') || document.activeElement.className : ''));
    // Undo and redo have nothing to do yet, so the first button that can take the focus is Print.
    expect(await stops()).toEqual(['print', 'bym-tb-select bym-tb-font', 'bym-tb-select bym-tb-size', 'bym-tb-select bym-tb-format']);

    await command(page, 'bold').focus();
    await page.keyboard.press('ArrowRight');
    expect(await focused()).toBe('italic');
    expect(await stops()).toEqual(['bym-tb-select bym-tb-font', 'bym-tb-select bym-tb-size', 'italic', 'bym-tb-select bym-tb-format']);
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('bold');
    // Print, PDF and Page setup are the only buttons before the font size list that can do something now; the arrows stop at the first.
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('pageSetup');
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('pdf');
    await page.keyboard.press('ArrowLeft');
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('print');
    await page.keyboard.press('End');
    expect(await focused()).toBe('find');
    await page.keyboard.press('ArrowRight');
    expect(await focused()).toBe('find');
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('rowsColumns');
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('chart');
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('validation');
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('conditionalFormat');
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('filter');
    await page.keyboard.press('ArrowLeft');
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('sortAscending');
    // The number format list lies between these two buttons.
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('mergeOptions');
    await page.keyboard.press('ArrowLeft');
    expect(await focused()).toBe('merge');
    await page.keyboard.press('Home');
    expect(await focused()).toBe('print');
    await page.keyboard.press('ArrowRight');
    expect(await focused()).toBe('pdf');
    await page.keyboard.press('ArrowRight');
    expect(await focused()).toBe('pageSetup');
    // The lists of fonts and of font sizes lie between these two buttons.
    await page.keyboard.press('ArrowRight');
    expect(await focused()).toBe('bold');
    await page.keyboard.press('ArrowRight');
    expect(await focused()).toBe('italic');

    // Enter presses the button, and the focus goes back to the grid.
    await page.keyboard.press('Enter');
    expect((await cell(page, 'A1')).italic).toBe(true);
    expect(await focused()).toBe('bym-input');
    await settled(page);
    // The button that was left is still the Tab stop, and now Undo can be reached from it.
    expect(await stops()).toEqual(['bym-tb-select bym-tb-font', 'bym-tb-select bym-tb-size', 'italic', 'bym-tb-select bym-tb-format']);
    await command(page, 'italic').focus();
    await page.keyboard.press('Home');
    expect(await focused()).toBe('undo');

    // Escape in the toolbar goes back to the grid too.
    await page.keyboard.press('Escape');
    expect(await focused()).toBe('bym-input');
  });

  test('Tab from the grid backwards reaches the formula bar and the toolbar', async ({ page, browserName, hasTouch }) => {
    test.skip(browserName === 'webkit', 'WebKit, like Safari, leaves buttons out of the Tab order unless the user turns that on');
    test.skip(!!hasTouch, 'Tab order is a matter of hardware keyboards; the desktop projects cover it');
    await mount(page, await editorWorkbook());
    await page.evaluate(() => (window as any).__editor.view.focus());
    const focused = () => page.evaluate(() => document.activeElement!.className);
    const order: string[] = [];
    for (let i = 0; i < 7; i++) {
      await page.keyboard.press('Shift+Tab');
      order.push(await page.evaluate(() => document.activeElement!.getAttribute('data-command') || document.activeElement!.id || document.activeElement!.className));
    }
    // The buttons are one stop (the first that can do something: nothing to undo yet, so Print); each list is its own.
    expect(order).toEqual(['bym-formula-input', 'bym-namebox', 'bym-tb-select bym-tb-format', 'bym-tb-select bym-tb-size', 'bym-tb-select bym-tb-font', 'print', 'before']);
    await page.keyboard.press('Tab');
    expect(await focused()).toBe('bym-tb-btn');
  });

  test('a menu opened with the keyboard is walked with the arrows; Escape closes it and gives the focus back to its button', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const button = command(page, 'borders');
    const focusedText = () => page.evaluate(() => (document.activeElement ? document.activeElement.textContent : ''));
    await button.focus();
    await page.keyboard.press('Enter');
    await expect(popover(page)).toBeVisible();
    expect(await focusedText()).toBe('All borders');
    await page.keyboard.press('ArrowDown');
    expect(await focusedText()).toBe('Outside borders');
    await page.keyboard.press('ArrowUp');
    await page.keyboard.press('ArrowUp');
    expect(await focusedText()).toBe('No borders');
    await page.keyboard.press('Home');
    expect(await focusedText()).toBe('All borders');
    await page.keyboard.press('Escape');
    await expect(popover(page)).toHaveCount(0);
    await expect(button).toBeFocused();
    await expect(button).toHaveAttribute('aria-expanded', 'false');
    expect((await cell(page, 'A1')).borders).toBe('');

    // Enter on an item applies it and returns to the grid.
    await page.keyboard.press('Enter');
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('Enter');
    await expect(popover(page)).toHaveCount(0);
    expect((await cell(page, 'A1')).borders).toBe('top right bottom left');
    expect(await focusedClass(page)).toBe('bym-input');
  });

  test('the palette is a grid for the arrow keys', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const button = command(page, 'fillColor');
    const focusedLabel = () => page.evaluate(() => (document.activeElement ? document.activeElement.getAttribute('data-color') || document.activeElement.textContent : ''));
    await button.focus();
    await page.keyboard.press('Enter');
    expect(await focusedLabel()).toBe('No fill');
    await page.keyboard.press('ArrowDown');
    expect(await focusedLabel()).toBe('#000000');
    await page.keyboard.press('ArrowRight');
    expect(await focusedLabel()).toBe('#434343');
    await page.keyboard.press('ArrowDown');
    expect(await focusedLabel()).toBe('#FF0000');
    await page.keyboard.press('ArrowLeft');
    expect(await focusedLabel()).toBe('#980000');
    await page.keyboard.press('End');
    expect(await focusedLabel()).toBe('#4C1130');
    await page.keyboard.press('ArrowDown');
    expect(await focusedLabel()).toBe('#4C1130');
    await page.keyboard.press('ArrowUp');
    expect(await focusedLabel()).toBe('#A64D79');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'A1')).fill).toBe('#A64D79');
    expect(await focusedClass(page)).toBe('bym-input');

    // Tab closes it like Escape does.
    await button.focus();
    await page.keyboard.press('Enter');
    await expect(popover(page)).toBeVisible();
    await page.keyboard.press('Tab');
    await expect(popover(page)).toHaveCount(0);
    await expect(button).toBeFocused();
  });

  test('after a command the next key goes to the grid', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    await page.evaluate(() => (window as any).__editor.view.focus());
    await press(command(page, 'bold'));
    expect(await focusedClass(page)).toBe('bym-input');
    await page.keyboard.press('ArrowDown');
    expect(await selection(page)).toBe('A2');

    await press(command(page, 'textColor'));
    await press(popover(page).locator('[data-color="#0000FF"]'));
    await page.keyboard.press('ArrowDown');
    expect(await selection(page)).toBe('A3');

    await page.locator('#host .bym-tb-size').selectOption('18');
    await page.keyboard.press('ArrowRight');
    expect(await selection(page)).toBe('B3');
    expect((await cell(page, 'A3')).size).toBe(18);
    expect((await cell(page, 'A2')).color).toBe('#0000FF');
  });

  test('a mouse press on a toolbar button does not take the focus out of the grid', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, 'about the mouse; a tap is covered by the test above');
    await mount(page, await editorWorkbook());
    await page.evaluate(() => (window as any).__editor.view.focus());
    const box = (await command(page, 'italic').boundingBox())!;
    await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
    await page.mouse.down();
    expect(await focusedClass(page)).toBe('bym-input');
    await page.mouse.up();
    expect((await cell(page, 'A1')).italic).toBe(true);
    expect(await focusedClass(page)).toBe('bym-input');
  });
});

test.describe('name box', () => {
  test('shows the active cell or the selected range', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const box = page.locator('#host .bym-namebox');
    await expect(box).toHaveValue('A1');
    await expect(box).toHaveAttribute('aria-label', 'Name box');
    await select(page, 'A1:B3');
    await expect(box).toHaveValue('A1:B3');
    await page.evaluate(() => (window as any).__editor.view.focus());
    await page.keyboard.press('ArrowDown');
    await expect(box).toHaveValue('A2');
  });

  test('an address typed into it is selected; anything else puts the old address back', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const box = page.locator('#host .bym-namebox');
    await box.fill('B7');
    await box.press('Enter');
    expect(await selection(page)).toBe('B7');
    await expect(box).toHaveValue('B7');
    expect(await focusedClass(page)).toBe('bym-input');
    await page.keyboard.press('ArrowDown');
    expect(await selection(page)).toBe('B8');
    await expect(box).toHaveValue('B8');

    // Lower case, corners in any order, absolute markers.
    await box.fill(' c3:$a$1 ');
    await box.press('Enter');
    expect(await selection(page)).toBe('A1:C3');
    await expect(box).toHaveValue('A1:C3');

    for (const bad of ['hello!', 'A0', 'XFE1', 'A1048577', '', '=1+1', 'A1:']) {
      await box.fill(bad);
      await box.press('Enter');
      await expect(box, bad).toHaveValue('A1:C3');
      expect(await selection(page), bad).toBe('A1:C3');
      await expect(box).toBeFocused();
    }

    // Escape and leaving the box drop what was typed.
    await box.fill('Z9');
    await box.press('Escape');
    await expect(box).toHaveValue('A1:C3');
    expect(await focusedClass(page)).toBe('bym-input');
    await box.fill('Z9');
    await page.locator('#after').focus();
    await expect(box).toHaveValue('A1:C3');
    expect(await selection(page)).toBe('A1:C3');
  });
});

test.describe('formula bar', () => {
  test('shows what the active cell holds: numbers in the locale, formulas with their sign', async ({ page }) => {
    await mount(page, await editorWorkbook(), { locale: 'tr' });
    const content = page.locator('#host .bym-formula-input');
    await expect(content).toHaveValue('1');
    await expect(content).toHaveAttribute('aria-label', 'Hücre içeriği');
    await select(page, 'C1');
    await expect(content).toHaveValue('=A1+B1');
    await select(page, 'A2');
    await expect(content).toHaveValue('10,5');
    await select(page, 'A3');
    await expect(content).toHaveValue('text');
    await select(page, 'F9');
    await expect(content).toHaveValue('');
    await expect(page.locator('#host .bym-fx')).toHaveText('fx');
  });

  test('typing in it edits the cell; Enter writes it and returns to the grid', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const content = page.locator('#host .bym-formula-input');
    await content.fill('77');
    expect(await page.evaluate(() => (window as any).__editor.view.isEditing)).toBe(true);
    expect(await page.evaluate(() => (window as any).__editor.view.editText)).toBe('77');
    // The editor in the grid shows the same text; the cell is not written yet.
    await expect(page.locator('#host .bym-input')).toHaveValue('77');
    expect((await cell(page, 'A1')).value).toBe(1);
    await expect(content).toBeFocused();

    await content.press('Enter');
    expect((await cell(page, 'A1')).value).toBe(77);
    expect(await page.evaluate(() => (window as any).__editor.view.isEditing)).toBe(false);
    expect(await focusedClass(page)).toBe('bym-input');
    await expect(content).toHaveValue('77');
    await expect(command(page, 'undo')).toBeEnabled();
  });

  test('typed key by key the caret stays where it is', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const content = page.locator('#host .bym-formula-input');
    await select(page, 'A3');
    await expect(content).toHaveValue('text');
    await content.focus();
    await content.evaluate((input: HTMLInputElement) => input.setSelectionRange(2, 2));
    await page.keyboard.type('XY');
    await expect(content).toHaveValue('teXYxt');
    expect(await content.evaluate((input: HTMLInputElement) => input.selectionStart)).toBe(4);
    await settled(page);
    await page.keyboard.type('Z');
    await expect(content).toHaveValue('teXYZxt');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'A3')).value).toBe('teXYZxt');
  });

  test('Escape drops the edit and Tab writes it', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const content = page.locator('#host .bym-formula-input');
    await content.fill('oops');
    await content.press('Escape');
    expect(await page.evaluate(() => (window as any).__editor.view.isEditing)).toBe(false);
    expect((await cell(page, 'A1')).value).toBe(1);
    await expect(content).toHaveValue('1');
    expect(await focusedClass(page)).toBe('bym-input');

    await content.fill('=B1*2');
    await content.press('Tab');
    expect((await cell(page, 'A1')).formula).toBe('B1*2');
    expect(await focusedClass(page)).toBe('bym-input');
    expect(await selection(page)).toBe('A1');
  });

  test('what is typed in the cell shows in the bar, and the bar can take the edit over', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const content = page.locator('#host .bym-formula-input');
    await page.evaluate(() => (window as any).__editor.view.focus());
    await page.keyboard.type('42');
    expect(await page.evaluate(() => (window as any).__editor.view.isEditing)).toBe(true);
    await expect(content).toHaveValue('42');
    await page.keyboard.press('Escape');
    await expect(content).toHaveValue('1');

    await page.keyboard.type('5');
    await expect(content).toHaveValue('5');
    // Moving to the bar keeps the edit open, with what was typed so far.
    await content.focus();
    expect(await page.evaluate(() => (window as any).__editor.view.isEditing)).toBe(true);
    await expect(content).toHaveValue('5');
    expect((await cell(page, 'A1')).value).toBe(1);
    await content.evaluate((input: HTMLInputElement) => input.setSelectionRange(1, 1));
    await page.keyboard.type('6');
    await expect(page.locator('#host .bym-input')).toHaveValue('56');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'A1')).value).toBe(56);
  });

  test('leaving the editor while the bar edits writes the cell', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const content = page.locator('#host .bym-formula-input');
    await content.fill('88');
    await page.locator('#after').focus();
    await expect.poll(async () => (await cell(page, 'A1')).value).toBe(88);
    expect(await page.evaluate(() => (window as any).__editor.view.isEditing)).toBe(false);
  });

  test('a toolbar command during an edit from the bar writes the cell first', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    await page.locator('#host .bym-formula-input').fill('31');
    await press(command(page, 'bold'));
    const a1 = await cell(page, 'A1');
    expect(a1.value).toBe(31);
    expect(a1.bold).toBe(true);
    expect(await focusedClass(page)).toBe('bym-input');
  });
});

test.describe('status bar', () => {
  test('adds up the selected numbers in the format of the locale', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const summary = page.locator('#host .bym-status-summary');
    await expect(page.locator('#host .bym-status')).toHaveAttribute('aria-label', 'Status bar');
    await expect(summary).toHaveText('');
    await select(page, 'A1:B2');
    await expect(summary).toHaveText('Sum: 33.75 · Average: 8.4375 · Count: 4');
    // Text counts as a cell but not as a number.
    await select(page, 'A1:A3');
    await expect(summary).toHaveText('Sum: 11.5 · Average: 5.75 · Count: 3');
    // Empty cells around the data change nothing; a formula's value is a number like any other.
    await select(page, 'A1:J40');
    await expect(summary).toHaveText('Sum: 40.75 · Average: 6.791666667 · Count: 7');
    // One cell, or no number: nothing to say.
    await select(page, 'B2');
    await expect(summary).toHaveText('');
    await select(page, 'A3:B4');
    await expect(summary).toHaveText('');
    await select(page, 'F5:H9');
    await expect(summary).toHaveText('');

    await page.evaluate(() => (window as any).__editor.setLocale('tr'));
    await select(page, 'A1:B2');
    await expect(summary).toHaveText('Toplam: 33,75 · Ortalama: 8,4375 · Sayı: 4');
  });

  test('follows edits and the sheet shown', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const summary = page.locator('#host .bym-status-summary');
    await select(page, 'A1:B1');
    await expect(summary).toHaveText('Sum: 3 · Average: 1.5 · Count: 2');
    await page.evaluate(() => {
      const view = (window as any).__editor.view;
      view.setCellInput(0, 1, '0.25');
      view.select({ top: 0, left: 0, bottom: 0, right: 1 });
    });
    await expect(summary).toHaveText('Sum: 1.25 · Average: 0.625 · Count: 2');
    await page.evaluate(() => (window as any).__editor.view.undo());
    await expect(summary).toHaveText('Sum: 3 · Average: 1.5 · Count: 2');
    await page.evaluate(() => (window as any).__editor.view.setActiveSheet(1));
    await expect(summary).toHaveText('');
    await expect(page.locator('#host .bym-namebox')).toHaveValue('A1');
    await expect(page.locator('#host .bym-formula-input')).toHaveValue('5');
  });

  test('a whole sheet is summed over its used area, and not at all when that is too large', async ({ page }) => {
    await mount(page, await editorWorkbook());
    const summary = page.locator('#host .bym-status-summary');
    const all = { top: 0, left: 0, bottom: MAX_ROWS - 1, right: MAX_COLS - 1 };
    await page.evaluate((range) => (window as any).__editor.view.select(range), all);
    await expect(summary).toHaveText('Sum: 40.75 · Average: 6.791666667 · Count: 7');

    await mount(page, await wideWorkbook());
    await select(page, 'A1:B1');
    await expect(summary).toHaveText('Sum: 3 · Average: 1.5 · Count: 2');
    const started = Date.now();
    await page.evaluate((range) => (window as any).__editor.view.select(range), all);
    await expect(summary).toHaveText('');
    await settled(page);
    await expect(summary).toHaveText('');
    expect(Date.now() - started).toBeLessThan(5000);
    // 200,000 cells of the used area are still added up: 664 rows of 301 columns include the first two numbers.
    await select(page, 'A1:XFD664');
    await expect(summary).toHaveText('Sum: 3 · Average: 1.5 · Count: 2');
  });
});

test.describe('read-only', () => {
  test('disables every editing control, locks the formula bar and says so', async ({ page }) => {
    await mount(page, await editorWorkbook(), { readOnly: true });
    const controls = page.locator('#host .bym-toolbar button, #host .bym-toolbar select');
    await expect(controls).toHaveCount(32);
    // Printing, making a PDF and finding change nothing: their buttons are the controls that stay on (the page setup would change the file).
    expect(await controls.evaluateAll((all) => all.filter((control) => !(control as HTMLButtonElement).disabled).map((control) => control.getAttribute('data-command')))).toEqual(['print', 'pdf', 'find']);
    await expect(page.locator('#host .bym-formula-input')).toHaveAttribute('readonly', '');
    const badge = page.locator('#host .bym-status-badge');
    await expect(badge).toBeVisible();
    await expect(badge).toHaveText('Read-only');

    // Looking around still works: the name box, the format shown, the sums.
    await select(page, 'D1');
    await expect(command(page, 'bold')).toHaveAttribute('aria-pressed', 'true');
    const box = page.locator('#host .bym-namebox');
    await box.fill('A1:B2');
    await box.press('Enter');
    expect(await selection(page)).toBe('A1:B2');
    await expect(page.locator('#host .bym-status-summary')).toHaveText('Sum: 33.75 · Average: 8.4375 · Count: 4');

    await page.evaluate(() => (window as any).__editor.setReadOnly(false));
    await expect(badge).toBeHidden();
    await expect(command(page, 'bold')).toBeEnabled();
    await expect(page.locator('#host .bym-tb-format')).toBeEnabled();
    await expect(command(page, 'undo')).toBeDisabled();
    expect(await page.locator('#host .bym-formula-input').getAttribute('readonly')).toBeNull();

    await page.evaluate(() => (window as any).__editor.setReadOnly(true));
    await expect(badge).toBeVisible();
    await expect(command(page, 'bold')).toBeDisabled();
  });

  test('turned on while a menu is open, the menu closes', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await editorWorkbook());
    await press(command(page, 'borders'));
    await expect(popover(page)).toBeVisible();
    await page.evaluate(() => (window as any).__editor.setReadOnly(true));
    await expect(popover(page)).toHaveCount(0);
    await expect(command(page, 'borders')).toBeDisabled();
  });
});

